// Column builders shared by the domain tables. Not re-exported from ./index.
// Schema files use relative imports only: drizzle-kit loads them without the
// `@/` path alias.
import { type AnyColumn, type SQL, sql } from "drizzle-orm";
import { bigint, date, text, timestamp, uuid } from "drizzle-orm/pg-core";
import { uuidv7 } from "uuidv7";
import { user } from "./auth";

/**
 * `id uuid primary key`. Ids are UUIDv7 generated by the app; callers may pass
 * their own (the client does, for idempotent inserts).
 */
export const idColumn = () =>
  uuid("id")
    .primaryKey()
    .$defaultFn(() => uuidv7());

/** `user_id text not null references "user"(id) on delete cascade` */
export const userIdColumn = () =>
  text("user_id")
    .notNull()
    .references(() => user.id, { onDelete: "cascade" });

/** Money in cents: `bigint`, read as a JS number (exact up to 2^53). */
export const cents = (name: string) => bigint(name, { mode: "number" });

/** Calendar date without time or zone, as `YYYY-MM-DD`. */
export const localDate = (name: string) => date(name, { mode: "string" });

export const timestamptz = (name: string) =>
  timestamp(name, { withTimezone: true });

export const createdAt = () => timestamptz("created_at").notNull().defaultNow();

/** Also refreshed by Drizzle on every `update()` that does not set it. */
export const updatedAt = () =>
  timestamptz("updated_at")
    .notNull()
    .defaultNow()
    .$onUpdate(() => new Date());

/** `column in ('a', 'b')` with inlined literals: CHECK constraints take no bind parameters. */
export function oneOf(column: AnyColumn, values: readonly string[]): SQL {
  const list = values.map((value) => `'${value.replaceAll("'", "''")}'`);
  return sql`${column} in (${sql.raw(list.join(", "))})`;
}
